#!/usr/bin/env python3
"""Deliver a proved mirror of canonical master; never execute the PR's code."""
from __future__ import annotations

import argparse
import hashlib
import json
import os
from pathlib import Path
import subprocess
import sys

REPO = "cirwel/unitares-governance-plugin"
SOURCE = "https://github.com/cirwel/unitares.git"
BRANCH = "auto/plugin-skill-sync"
MANIFEST = "SKILLS_MANIFEST.sha256"
HEADER = (
    "# Canonical fingerprint of unitares/skills/ — generated by\n"
    "# scripts/dev/skills_manifest.py. Do not hand-edit; run the script.\n"
    "# Consumers (e.g. the plugin mirror) verify their copy against this file.\n"
)


class Hold(Exception):
    """The automation cannot establish that this PR is ready to deliver."""


def git(*args: str) -> bytes:
    result = subprocess.run(["git", *args], capture_output=True, check=False)
    if result.returncode:
        raise Hold("Git verification failed; no merge attempted")
    return result.stdout


def api(path: str, method: str = "GET", body=None):
    command = ["gh", "api", "--method", method, f"repos/{REPO}/{path}"]
    if body is not None:
        command += ["--input", "-"]
    result = subprocess.run(command, input=None if body is None else json.dumps(body),
                            text=True, capture_output=True, check=False)
    if result.returncode:
        # Error bodies can contain untrusted content. Keep the hold bounded.
        raise Hold(f"GitHub {method} {path.split('?')[0]} failed; no bypass attempted")
    return json.loads(result.stdout) if result.stdout else None


def candidate(pr: dict) -> bool:
    return (pr.get("state") == "open" and not pr.get("draft")
            and pr.get("head", {}).get("ref") == BRANCH
            and (pr.get("head", {}).get("repo") or {}).get("full_name") == REPO
            and pr.get("base", {}).get("ref") == "master"
            and (pr.get("base", {}).get("repo") or {}).get("full_name") == REPO)


def require_checks(runs: list[dict], head: str) -> None:
    eligible = [r for r in runs if r.get("path") == ".github/workflows/ci.yml"
                and r.get("event") == "pull_request" and r.get("head_sha") == head
                and (r.get("head_repository") or {}).get("full_name") == REPO]
    latest = max(eligible, key=lambda r: r["id"], default=None)
    if not latest or latest.get("status") != "completed" or latest.get("conclusion") != "success":
        raise Hold("The latest CI run for this exact PR head has not passed")


def tree(ref: str) -> dict[str, tuple[str, str, str]]:
    entries = {}
    for record in git("ls-tree", "-r", "-z", f"{ref}:skills").split(b"\0"):
        if not record:
            continue
        metadata, name = record.split(b"\t", 1)
        mode, kind, oid = metadata.decode("ascii").split()
        if kind != "blob" or mode not in ("100644", "100755"):
            raise Hold("Mirror contains a symlink or non-file entry")
        entries[name.decode("utf-8")] = (mode, kind, oid)
    if not entries:
        raise Hold("Canonical or mirror skills tree is empty")
    return entries


def verify_content(source: str, head: str, base: str) -> None:
    # Three-dot diff measures PR-authored changes even when master moved.
    paths = git("diff", "--name-only", "-z", f"{base}...{head}").split(b"\0")
    changed = [p for p in paths if p]
    if not changed or any(not p.startswith(b"skills/") for p in changed):
        raise Hold("PR must change only the skills mirror")
    canonical, mirror = tree(source), tree(head)
    canonical.pop(MANIFEST, None)
    manifest = mirror.pop(MANIFEST, None)
    if canonical != mirror:
        raise Hold("Mirror differs from canonical master (including attestations and file modes)")
    if not manifest or manifest[0] != "100644":
        raise Hold("Mirror manifest is missing or executable")
    lines = []
    for name, (_, _, oid) in sorted(canonical.items()):
        if Path(name).name == MANIFEST or ".attestations" in Path(name).parts:
            continue
        digest = hashlib.sha256(git("cat-file", "blob", oid)).hexdigest()
        lines.append(f"{digest}  {name}")
    body = "\n".join(lines)
    aggregate = hashlib.sha256(body.encode()).hexdigest()
    expected = f"{HEADER}# aggregate: {aggregate}\n{body}\n".encode()
    if git("cat-file", "blob", manifest[2]) != expected:
        raise Hold("Mirror manifest does not match independently computed canonical content")


def deliver(number: int, *, apply: bool) -> str:
    pr = api(f"pulls/{number}")
    if not candidate(pr):
        raise Hold("PR is not an open, ready mirror from the owned automation branch")
    if any(label["name"] in ("automerge-hold", "do-not-merge", "governance-sensitive")
           for label in pr.get("labels", [])):
        raise Hold("A maintainer hold label is present")
    head = pr["head"]["sha"]
    # A pull's base.sha can remain at its original snapshot after master moves.
    # Read the actual branch for ancestry, fetch validation and race checks.
    base = api("branches/master")["commit"]["sha"]
    runs = api(f"actions/runs?event=pull_request&head_sha={head}&per_page=100")
    require_checks(runs["workflow_runs"], head)
    # Fixed remotes/refspecs only. Fetch data, never check out or import PR code.
    git("fetch", "--quiet", "--no-tags", "origin",
        f"+refs/pull/{number}/head:refs/mirror/head", "+refs/heads/master:refs/mirror/base")
    git("fetch", "--quiet", "--no-tags", SOURCE, "+refs/heads/master:refs/mirror/source")
    if git("rev-parse", "refs/mirror/head").decode().strip() != head:
        raise Hold("PR head moved while fetching; the next CI completion will retry")
    if git("rev-parse", "refs/mirror/base").decode().strip() != base:
        raise Hold("Plugin base moved while fetching; re-evaluate against its new head")
    source = git("rev-parse", "refs/mirror/source").decode().strip()
    verify_content(source, head, base)
    # Re-read holds and both refs immediately before a write. GitHub's merge
    # SHA and strict required-check rules are the final concurrent-write guards.
    fresh = api(f"pulls/{number}")
    if (not candidate(fresh) or fresh["head"]["sha"] != head
            or fresh["base"]["sha"] != pr["base"]["sha"]
            or api("branches/master")["commit"]["sha"] != base
            or fresh.get("labels") != pr.get("labels")):
        raise Hold("PR state changed during verification")
    behind = subprocess.run(["git", "merge-base", "--is-ancestor", base, head]).returncode
    if behind not in (0, 1):
        raise Hold("Could not establish base ancestry")
    if not apply:
        return f"Verified #{number} at {head}; canonical {source}; action={'update base' if behind else 'merge'}"
    if behind:
        api(f"pulls/{number}/update-branch", "PUT", {"expected_head_sha": head})
        return f"Updated #{number} to the current base; waiting for new CI before merging"
    run_id = os.environ.get("GITHUB_RUN_ID", "")
    provenance = (f"https://github.com/{REPO}/actions/runs/{run_id}"
                  if run_id.isdigit() else "local verified-delivery helper")
    result = api(f"pulls/{number}/merge", "PUT", {
        "sha": head, "merge_method": "squash",
        "commit_title": f"chore(skills): deliver verified canonical mirror (#{number})",
        "commit_message": f"Verified byte mirror of cirwel/unitares at {source}.\n"
                          f"PR head: {head}\nDelivery: {provenance}",
    })
    if not result.get("merged"):
        raise Hold("GitHub did not merge the verified head; protections remain in force")
    return f"Merged #{number}: canonical {source}, PR head {head}, merge {result['sha']}"


def main(argv=None) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--pr", type=int)
    parser.add_argument("--apply", action="store_true")
    args = parser.parse_args(argv)
    try:
        if args.pr:
            numbers = [args.pr]
        else:
            prs = api(f"pulls?state=open&head=cirwel:{BRANCH}&base=master&per_page=100")
            numbers = [p["number"] for p in prs if candidate(p)]
        if len(numbers) > 1:
            raise Hold("Multiple mirror PRs require reconciliation")
        messages = [deliver(n, apply=args.apply) for n in numbers] or ["No open mirror PR to deliver"]
        status = 0
    except (Hold, KeyError, ValueError) as exc:
        messages, status = [f"Mirror delivery held: {exc}"], 1
    for message in messages:
        print(message)
    if os.environ.get("GITHUB_STEP_SUMMARY"):
        with open(os.environ["GITHUB_STEP_SUMMARY"], "a") as summary:
            summary.write("\n".join(messages) + "\n")
    return status


if __name__ == "__main__":
    sys.exit(main())
